import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { readFile, writeFile, mkdtemp, rm } from 'node:fs/promises';
import { dirname, resolve, join } from 'node:path';
import { tmpdir } from 'node:os';
import { createServer } from 'vite';
import { launchRenderBrowser, probeRenderEnvironment, assertPinnedRenderEnvironment } from '@still-shift/execution-runtime';
import { compileCommerceComposition } from '@still-shift/animation-engine';
import { storyToComposition } from '@still-shift/renderer-core';
import { CommerceSceneSchema, StorySceneSchema } from '@still-shift/scene-contract';
import { commerceEffectVariants } from '../../../tests/helpers/composition-effects.ts';
const root = resolve(import.meta.dirname, '../../..');
const option = (key: string, fallback: string) => { const i = process.argv.indexOf(key); return i < 0 ? fallback : process.argv[i+1]!; };
const profile = process.argv.includes('--hardware') ? 'hardware' : 'pinned';
const hashesOnly = process.argv.includes('--hashes-only');
const pixelsOnly = process.argv.includes('--pixels-only');
const countsOnly = process.argv.includes('--counts-only') || hashesOnly || pixelsOnly;
const sourceRef = option('--ref','');
const cases = option('--cases', 'native').split(',');
const output = resolve(option('--output', `benchmarks/results/composition-ce6p/diagnosis-${Date.now()}.json`));
const digest = (value: string) => createHash('sha256').update(value).digest('hex');
const paths = execFileSync('git',['ls-files','packages/renderer-core/src','packages/scene-contract/src','packages/animation-engine/src'],{cwd:root,encoding:'utf8'}).trim().split('\n').filter(p=>p.endsWith('.ts'));
paths.push('packages/renderer-core/src/composition/render/webgl-disjoint-paints.ts','tests/helpers/composition-webgl-disjoint-paints.ts','tests/helpers/composition-effects.ts','tests/helpers/composition-commerce-masks.ts','tests/helpers/composition-webgl-performance.ts');
const snapshots = new Map<string,string>();
for(const path of paths){if(sourceRef){if(!execFileSync('git',['ls-tree','--name-only',sourceRef,path],{cwd:root,encoding:'utf8'}).trim())continue;snapshots.set(join(root,path),execFileSync('git',['show',`${sourceRef}:${path}`],{cwd:root,encoding:'utf8'}));}else snapshots.set(join(root,path),await readFile(join(root,path),'utf8'));}
const helperPath = 'benchmarks/results/composition-ce6p/diagnose-browser.mjs';
const helperSource = await readFile(join(root,helperPath),'utf8');
const diagnosticSource = await readFile(import.meta.filename,'utf8');
snapshots.set(join(root,helperPath),helperSource);
const workloads = () => execFileSync('ps',['-axo','pid,command'],{encoding:'utf8'}).split('\n').filter(line=> {
  const m=/^\s*(\d+)\s+(\S+)\s+(.*)$/.exec(line); if(!m || +m[1]===process.pid)return false;
  const bin=m[2]!.split('/').at(-1), args=m[3]!;
  return bin==='pnpm' || bin==='vitest' || ((bin==='node'||bin==='tsx') && /(?:^|[/\s])pnpm(?:\.[cm]?js)?(?:\s|$)|vitest|tests\/(?:browser|integration|runtime)\//.test(args));
});
const competing=workloads(); if(!countsOnly && competing.length)throw Error(`No diagnosis started: ${competing.join('\n')}`);
let overlap:string[]=[];
const monitor=setInterval(()=>{try {const list=workloads(); if(list.length)overlap=list;}catch(e){overlap=[String(e)];}},2000);
const cache=await mkdtemp(join(tmpdir(),'ce6p-diagnosis-vite-'));
const server=await createServer({root,cacheDir:cache,configFile:false,logLevel:'error',plugins:[{name:'ce6p-diagnostic-snapshots',enforce:'pre',load(id){return snapshots.get(id);}}],server:{host:'127.0.0.1',port:0}});
let browser: Awaited<ReturnType<typeof launchRenderBrowser>> | undefined;
const report:any={date:new Date().toISOString(),profile,ref:execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8'}).trim(),sourceSha256:Object.fromEntries([...snapshots].map(([p,s])=>[p.slice(root.length+1),digest(s)])),diagnosticSha256:digest(diagnosticSource),sourceRef:sourceRef||'working-tree',hashesOnly,pixelsOnly,countsOnly,method:countsOnly?'Selected-frame operation counts only; no elapsed timings captured; concurrent workloads allowed for structural diagnosis.':'Instrumented first forward traversal; stage wall times include instrumentation and queued work. Separate post-render 1x1 read barrier attribution. Never acceptance or candidate speedup evidence.',cases:[]};
try {
 await server.listen(); browser=await launchRenderBrowser({profile});
 for(const name of cases){
  let composition:any; let urls={};
  if(name!=='native' && name!=='oracle' && name!=='bounded-particles'){
   const particleVariant=name.startsWith('particles/');
   const path=resolve(root,particleVariant ? 'benchmarks/fixtures/ecommerce-motion/atoms/particles.json' : name.includes('/') ? name : `benchmarks/fixtures/ecommerce-motion/atoms/${name}.json`);
   const source=await readFile(path,'utf8'); const input=JSON.parse(source); const commerce=input.schemaVersion==='commerce-scene-1';
   const scene=commerce ? CommerceSceneSchema.parse(input) : StorySceneSchema.parse(input);
   const chosen=particleVariant ? commerceEffectVariants('commerce/atom-particles', CommerceSceneSchema.parse(input)).find(v=>v.id.endsWith('/'+name.split('/')[1]))!.scene : scene;
   composition=commerce ? await compileCommerceComposition(CommerceSceneSchema.parse(chosen),dirname(path)) : storyToComposition(StorySceneSchema.parse(chosen));
   report.sourceSha256['generated-workload/'+name]=digest(JSON.stringify(chosen));
   urls=Object.fromEntries(composition.assets.map((a:any)=>[a.id,'/@fs'+resolve(dirname(path),a.path)]));
   report.sourceSha256[path.slice(root.length+1)]=digest(source);
  }
  const page=await browser.newPage(); await page.addInitScript('window.__name=(fn)=>fn;'); await page.goto(server.resolvedUrls!.local[0]!);
  const environment=await probeRenderEnvironment(page,profile); if(profile==='pinned')assertPinnedRenderEnvironment(environment);
  const result=await page.evaluate(async payload=>{
   const url='/benchmarks/results/composition-ce6p/diagnose-browser.mjs';
   const helper=await import(url);return helper.diagnose(payload);
  },{name,composition,urls,countsOnly,hashesOnly,pixelsOnly});
  report.cases.push({name,environment,...result});
  report.timingValid=countsOnly ? null : overlap.length===0 && workloads().length===0; report.overlap=overlap;
  await writeFile(output,JSON.stringify(report,null,2)+'\n');
  console.log(`${name}: retained ${output}; timingValid=${report.timingValid}`);
  if(!countsOnly && !report.timingValid)throw Error('Contaminated diagnosis retained; stop');
  await page.close();
 }
}finally{clearInterval(monitor);await Promise.all([browser?.close(),server.close()]);await rm(cache,{recursive:true,force:true});}

