import {createCompositionPreview,loadCompositionResources} from '../../../packages/renderer-core/src/index.ts';
import {WebglDevice} from '../../../packages/renderer-core/src/composition/render/webgl-device.ts';
import {WebglPaint} from '../../../packages/renderer-core/src/composition/render/webgl-paint.ts';
import {WebglVectors} from '../../../packages/renderer-core/src/composition/render/webgl-vectors.ts';
import {WebglReadback} from '../../../packages/renderer-core/src/composition/render/webgl-readback.ts';
const native=()=>({schemaVersion:'composition-1',id:'exposure-cost',width:1920,height:1080,fps:30,frameCount:60,background:'#26313b',assets:[],motionBlur:{enabled:false,shutterAngle:360,shutterPhase:0,samples:2},layers:[{id:'moving',type:'solid',size:[400,300],color:'#d87047',motionBlur:true,transform:{anchor:[0,0],position:{x:{keys:[{frame:0,value:100},{frame:59,value:1400,interpolation:'linear'}]},y:300},opacity:.6}}]});
export async function diagnose({name,composition,urls,countsOnly=false,hashesOnly=false,pixelsOnly=false}){
 if(name==='bounded-particles'){const url='/tests/helpers/composition-webgl-performance.ts';return {checked:await (await import(url)).checkWebglBoundedParticles(),elapsedTimingsCaptured:false};}
 if(name==='oracle'){const url='/tests/helpers/composition-webgl-disjoint-paints.ts';return (await import(url)).checkWebglDisjointPaints();}
 const comp=composition??native(); const canvas=document.createElement('canvas');
 const preview=createCompositionPreview(canvas,comp,await loadCompositionResources(comp,id=>urls[id]),{backend:'webgl2'});
 const gl=canvas.getContext('webgl2');
 const makeStats=()=>({});let stats=makeStats(), enabled=false;
 const restores=[]; const paintBatches=[];
 const rectArea=r=>r?(r.right-r.left)*(r.bottom-r.top):0;
 const add=(key,ms,pixels=0)=>{const s=stats[key]??={count:0,ms:0,pixels:0};s.count++;s.ms+=ms;s.pixels+=pixels;};
 const hook=(target,name,key,area=()=>0)=>{
  const original=target[name];target[name]=function(...args){if(enabled && key==='paint.drawMany')paintBatches.push({screen:args[1].screen,opaque:args[1].opaque,parts:args[0].map(p=>({rect:p.rect,primitive:p.primitive})),clear:args[0].length?this.device.solidColor(args[1],args[0][0].rect):undefined});if(!enabled)return Reflect.apply(original,this,args);const at=countsOnly?0:performance.now();try{return Reflect.apply(original,this,args);}finally{add(typeof key==='function'?key(args):key,countsOnly?0:performance.now()-at,area(args,this));}};
  restores.push(()=>target[name]=original);
 };
 for(const name of ['clear','copyRegion','uploadRegion','readRegion','pass','resolveScreen']){
  hook(WebglDevice.prototype,name,args=>name==='pass'?'pass:'+args[0].replace(/\s+/g,' ').slice(0,100):name,(args,self)=>{
   const dst=name==='pass'?args[1]:args[0]; if(name==='readRegion')return args[3]*args[4]; if(name==='copyRegion')return rectArea(args[1]);
   if(name==='pass' && dst)return rectArea(self.drawRegion(dst,args[5]??{left:0,top:0,right:dst.width,bottom:dst.height}));
   return dst?.width*dst?.height||0;
  });
 }
 hook(WebglPaint.prototype,'drawMany','paint.drawMany',args=>args[0].map(p=>rectArea(p.rect)).reduce((a,b)=>a+b,0));
 hook(WebglVectors.prototype,'paint','vector.prepare');hook(WebglVectors.prototype,'drawBatch','vector.drawBatch');hook(WebglReadback.prototype,'read','ownedRead');
 hook(Uint8ClampedArray.prototype,'slice','ownedSlice',(_args,self)=>self.length/4);
 hook(WebGL2RenderingContext.prototype,'texSubImage2D','gl.texSubImage2D');hook(WebGL2RenderingContext.prototype,'readPixels','gl.readPixels',args=>args[2]*args[3]);
 const traversal=(instrumented,barrier)=>{
  stats=makeStats();enabled=false;
  if(name==='native'){preview.renderFrame(20);preview.readPixels();}else{preview.renderFrame(0);preview.readPixels();}
  const frames=name==='native'?Array.from({length:8},(_,i)=>21+i):Array.from({length:comp.frameCount},(_,i)=>i);
  let renderMs=0,queueMs=0,readMs=0,count=0;const timings=[];
  for(const frame of frames){
   const measured=name!=='native'||frame>=24;enabled=instrumented&&measured;
   const at=performance.now();preview.renderFrame(frame);const afterRender=performance.now();
   if(barrier){const p=new Uint8Array(4);gl.bindFramebuffer(gl.FRAMEBUFFER,null);gl.readPixels(0,0,1,1,gl.RGBA,gl.UNSIGNED_BYTE,p);}
   const afterQueue=performance.now();preview.readPixels();const end=performance.now();
   if(measured){renderMs+=afterRender-at;queueMs+=afterQueue-afterRender;readMs+=end-afterQueue;count++;timings.push(end-at);}
  }
  enabled=false;return{frames:count,renderMs,queueMs,readMs,totalMs:renderMs+queueMs+readMs,timingsMs:timings,stats};
 };
 try{
  if(pixelsOnly){const frames=[];for(const frame of [0,24,96,comp.frameCount-1]){preview.renderFrame(frame);const pixels=preview.readPixels();const stream=new Blob([pixels]).stream().pipeThrough(new CompressionStream('deflate'));const encoded=new Uint8Array(await new Response(stream).arrayBuffer());let binary='';for(let i=0;i<encoded.length;i+=32768)binary+=String.fromCharCode(...encoded.subarray(i,i+32768));frames.push({frame,pixelsDeflateBase64:btoa(binary)});}return{size:[comp.width,comp.height],frames,elapsedTimingsCaptured:false};}
  if(hashesOnly){const hashes={};const repeated=[];const digest=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(v=>v.toString(16).padStart(2,'0')).join('');for(let frame=0;frame<comp.frameCount;frame++){preview.renderFrame(frame);hashes[frame]=await digest(preview.readPixels());}for(const frame of [...Array.from({length:comp.frameCount},(_,i)=>comp.frameCount-i-1),...Array.from({length:17},(_,i)=>(i*73+19)%comp.frameCount),...Array(3).fill(Math.floor(comp.frameCount/2))]){preview.renderFrame(frame);if(await digest(preview.readPixels())!==hashes[frame])throw Error('Seek/read mismatch '+frame);repeated.push(frame);}return{size:[comp.width,comp.height],frames:comp.frameCount,hashes,checkedSeeks:repeated.length,elapsedTimingsCaptured:false};}
  if(countsOnly){const frames=[];for(const frame of [...new Set(name==='native'?[20,24,28]:[0,24,96,comp.frameCount-1])].filter(f=>f<comp.frameCount)){stats=makeStats();paintBatches.length=0;enabled=true;preview.renderFrame(frame);preview.readPixels();enabled=false;frames.push({frame,stats,paintBatches:[...paintBatches]});}return{size:[comp.width,comp.height],frames,elapsedTimingsCaptured:false};}
  const first=traversal(true,false);const separated=traversal(true,true);
  const baselineCopy=new Uint8ClampedArray(comp.width*comp.height*4);const copies=[];
  for(let i=0;i<40;i++){const at=performance.now();const owned=baselineCopy.slice();copies.push(performance.now()-at);if(owned.length!==baselineCopy.length)throw Error('copy');}
  const repeated=traversal(false,false);
  return{size:[comp.width,comp.height],firstInstrumented:first,separatedInstrumented:separated,warmedUninstrumented:repeated,ownedCopyControlMs:copies};
 }finally{enabled=false;restores.reverse().forEach(r=>r());preview.dispose();}
}

