import { readFile,writeFile } from 'node:fs/promises';
import { inflateSync } from 'node:zlib';
import { compareFrames,meetsTier,strictestTier } from '../../../packages/renderer-core/src/frame-tolerance.ts';
const dir='benchmarks/results/composition-ce6p/';
const pinned=JSON.parse(await readFile(dir+'disjoint-pinned-sampled-pixels.json','utf8'));
const hardware=JSON.parse(await readFile(dir+'disjoint-hardware-sampled-pixels.json','utf8'));
const results=[];
for(const a of pinned.cases){const b=hardware.cases.find((c:any)=>c.name===a.name);for(const x of a.frames){const y=b.frames.find((f:any)=>f.frame===x.frame);const comparison=compareFrames(inflateSync(Buffer.from(x.pixelsDeflateBase64,'base64')),inflateSync(Buffer.from(y.pixelsDeflateBase64,'base64')),a.size[0],a.size[1]);results.push({case:a.name,frame:x.frame,...comparison,tier:strictestTier(comparison),perceptual:meetsTier(comparison,'perceptual')});}}
await writeFile(dir+'disjoint-sampled-profile-drift.json',JSON.stringify({method:'Four selected frames per particle variant, preserved preview/readback and unchanged perceptual tier; not a complete family hardware audit.',results},null,2)+'\n');
console.log(JSON.stringify(results,null,2));if(results.some(r=>!r.perceptual))process.exitCode=1;

