import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readFile, writeFile, mkdtemp, rm } from "node:fs/promises";
import { dirname, resolve, join } from "node:path";
import { tmpdir } from "node:os";
import { createServer } from "vite";
import {
  launchRenderBrowser,
  probeRenderEnvironment,
  assertPinnedRenderEnvironment,
} from "@still-shift/execution-runtime";
import { compileCommerceComposition } from "@still-shift/animation-engine";
import { compileCommerceScene } from "@still-shift/renderer-core";
import { CommerceSceneSchema } from "@still-shift/scene-contract";
import { commerceEffectVariants } from "../../../tests/helpers/composition-effects.ts";
const root = resolve(import.meta.dirname, "../../..");
const option = (key: string, fallback: string) => {
  const i = process.argv.indexOf(key);
  return i < 0 ? fallback : process.argv[i + 1]!;
};
const profile = process.argv.includes("--hardware") ? "hardware" : "pinned";
const preflightOnly = process.argv.includes("--preflight-only");
const sourceRef = option("--ref", "");
const cases = option("--cases", "particles").split(",");
const output = resolve(
  option(
    "--output",
    `benchmarks/results/composition-ce6p/particle-timing-${Date.now()}.json`,
  ),
);
const digest = (s: string | Buffer) =>
  createHash("sha256").update(s).digest("hex");
const workloads = () =>
  execFileSync("ps", ["-axo", "pid,command"], { encoding: "utf8" })
    .split("\n")
    .filter((line) => {
      const m = /^\s*(\d+)\s+(\S+)\s+(.*)$/.exec(line);
      if (!m || +m[1] === process.pid) return false;
      const bin = m[2]!.split("/").at(-1),
        args = m[3]!;
      return (
        bin === "pnpm" ||
        bin === "vitest" ||
        bin === "ffmpeg" ||
        ((bin === "node" || bin === "tsx") &&
          /(?:^|[/\s])pnpm(?:\.[cm]?js)?(?:\s|$)|vitest|(?:tests|benchmarks|scripts|apps)\//.test(
            args,
          ))
      );
    });
let cache: string | undefined,
  server: Awaited<ReturnType<typeof createServer>> | undefined,
  browser: Awaited<ReturnType<typeof launchRenderBrowser>> | undefined,
  monitor: ReturnType<typeof setInterval> | undefined;
let overlap: string[] = [];
const report: any = {
  status: "in-progress",
  date: new Date().toISOString(),
  profile,
  sourceRef: sourceRef || "working-tree",
  preflightOnly,
  timingValid: null,
  elapsedSessionInvoked: false,
  cases: [],
  method:
    "Controlled experiment using unchanged paired complete timeline render/readback helper (three alternating passes, at least 500 ms per side, at most 64 cycles). Warm one paired forward traversal and reverse candidate endpoints first. Strict acceptance still requires the original family audit.",
};
const retain = () => writeFile(output, JSON.stringify(report, null, 2) + "\n");
try {
  const paths = execFileSync(
    "git",
    [
      "ls-files",
      "packages/renderer-core/src",
      "packages/scene-contract/src",
      "packages/animation-engine/src",
    ],
    { cwd: root, encoding: "utf8" },
  )
    .trim()
    .split("\n")
    .filter((p) => p.endsWith(".ts"));
  paths.push(
    "packages/renderer-core/src/composition/render/webgl-disjoint-paints.ts",
    "tests/helpers/composition-effects.ts",
    "tests/helpers/composition-commerce-masks.ts",
    "tests/helpers/paired-render-timing.ts",
  );
  const snapshots = new Map<string, string>();
  report.hostSourceSha256 = {};
  report.sourceSha256 = {};
  for (const path of paths) {
    const actual = await readFile(join(root, path), "utf8");
    report.hostSourceSha256[path] = digest(actual);
    if (sourceRef) {
      if (
        !execFileSync("git", ["ls-tree", "--name-only", sourceRef, path], {
          cwd: root,
          encoding: "utf8",
        }).trim()
      )
        continue;
      snapshots.set(
        join(root, path),
        execFileSync("git", ["show", `${sourceRef}:${path}`], {
          cwd: root,
          encoding: "utf8",
        }),
      );
    } else snapshots.set(join(root, path), actual);
  }
  const helperPath =
    "benchmarks/results/composition-ce6p/particle-timing-browser.mjs";
  const helperSource = await readFile(join(root, helperPath), "utf8");
  snapshots.set(join(root, helperPath), helperSource);
  for (const [path, source] of snapshots)
    report.sourceSha256[path.slice(root.length + 1)] = digest(source);
  report.ref = execFileSync("git", ["rev-parse", "HEAD"], {
    cwd: root,
    encoding: "utf8",
  }).trim();
  report.diagnosticSha256 = digest(
    await readFile(import.meta.filename, "utf8"),
  );
  report.hostCompiler =
    "Shared actual working-tree Node compiler and variant helper; actual host hashes and exact supplied composition/legacy/URL payload hashes are recorded separately from injected browser sources.";
  report.competingAtStartup = workloads();
  if (!preflightOnly && report.competingAtStartup.length) {
    report.status = "rejected-before-browser-start";
    throw Error("Competing workloads: elapsed session not started");
  }
  monitor = setInterval(() => {
    try {
      overlap = [...new Set([...overlap, ...workloads()])];
    } catch (e) {
      overlap = [...overlap, String(e)];
    }
  }, 2000);
  cache = await mkdtemp(join(tmpdir(), "ce6p-particle-timing-"));
  server = await createServer({
    root,
    cacheDir: cache,
    configFile: false,
    logLevel: "error",
    plugins: [
      {
        name: "ce6p-immutable-sources",
        enforce: "pre",
        load(id) {
          return snapshots.get(id);
        },
      },
    ],
    server: { host: "127.0.0.1", port: 0 },
  });
  await server.listen();
  browser = await launchRenderBrowser({ profile });
  await retain();
  for (const name of cases) {
    const variant = name.startsWith("particles/");
    const path = resolve(
      root,
      variant
        ? "benchmarks/fixtures/ecommerce-motion/atoms/particles.json"
        : `benchmarks/fixtures/ecommerce-motion/atoms/${name}.json`,
    );
    const source = await readFile(path, "utf8");
    const input = CommerceSceneSchema.parse(JSON.parse(source));
    const scene = variant
      ? commerceEffectVariants("commerce/atom-particles", input).find((v) =>
          v.id.endsWith("/" + name.split("/")[1]),
        )!.scene
      : input;
    const composition = await compileCommerceComposition(scene, dirname(path));
    const legacyScene = compileCommerceScene(scene);
    const urls = Object.fromEntries(
      composition.assets.map((a) => [
        a.id,
        "/@fs" + resolve(dirname(path), a.path),
      ]),
    );
    report.sourceSha256[path.slice(root.length + 1)] = digest(source);
    const suppliedPayloadSha256 = {
      composition: digest(JSON.stringify(composition)),
      legacyScene: digest(JSON.stringify(legacyScene)),
      urls: digest(JSON.stringify(urls)),
    };
    const page = await browser.newPage();
    await page.addInitScript("window.__name=(fn)=>fn;");
    await page.goto(server.resolvedUrls!.local[0]!);
    const environment = await probeRenderEnvironment(page, profile);
    if (profile === "pinned") assertPinnedRenderEnvironment(environment);
    report.elapsedSessionInvoked = !preflightOnly;
    const result = await page.evaluate(
      async (payload) => {
        const url =
          "/benchmarks/results/composition-ce6p/particle-timing-browser.mjs";
        return (await import(url)).measure(payload);
      },
      { composition, legacyScene, urls, preflightOnly },
    );
    report.cases.push({ name, suppliedPayloadSha256, environment, ...result });
    overlap = [...new Set([...overlap, ...workloads()])];
    report.overlap = overlap;
    report.timingValid = preflightOnly ? null : overlap.length === 0;
    await retain();
    console.log(
      `${name}: retained ${output}; timingValid=${report.timingValid}`,
    );
    if (!preflightOnly && !report.timingValid)
      throw Error("Contaminated measurement retained; stop");
    await page.close();
  }
  report.status = "complete";
  await retain();
} catch (error) {
  if (report.status !== "rejected-before-browser-start")
    report.status = "failed";
  report.error = String(error);
  report.overlap = overlap;
  report.timingValid = preflightOnly ? null : false;
  await retain();
  throw error;
} finally {
  if (monitor) clearInterval(monitor);
  try {
    const closed = await Promise.allSettled([
      browser?.close(),
      server?.close(),
    ]);
    const failed = closed.filter((r) => r.status === "rejected");
    if (failed.length) {
      report.status = "cleanup-failed";
      report.timingValid = false;
      report.cleanupErrors = failed.map(
        (r) =>
          (r as PromiseRejectedResult).reason?.message ??
          String((r as PromiseRejectedResult).reason),
      );
      await retain();
      process.exitCode = 1;
    }
  } finally {
    if (cache) await rm(cache, { recursive: true, force: true });
  }
}

import {
  createCompositionPreview,
  loadCompositionResources,
  createIllustratedPreview,
  loadIllustratedImages,
} from "../../../packages/renderer-core/src/index.ts";
import { measurePairedRenderTimings } from "../../../tests/helpers/paired-render-timing.ts";
export async function measure({
  composition,
  legacyScene,
  urls,
  preflightOnly,
}) {
  let legacy, preview;
  try {
    const resources = await loadCompositionResources(
      composition,
      (id) => urls[id],
    );
    const oldCanvas = document.createElement("canvas"),
      canvas = document.createElement("canvas");
    legacy = createIllustratedPreview(
      oldCanvas,
      legacyScene,
      await loadIllustratedImages(legacyScene, (id) => urls[id]),
    );
    preview = createCompositionPreview(canvas, composition, resources, {
      backend: "webgl2",
    });
    const ctx = oldCanvas.getContext("2d");
    const readLegacy = () =>
      ctx.getImageData(0, 0, canvas.width, canvas.height);
    if (preflightOnly) {
      for (const frame of [0, 24, 96, composition.frameCount - 1]) {
        legacy.renderFrame(frame);
        readLegacy();
        preview.renderFrame(frame);
        preview.readPixels();
      }
      return {
        rendererVersion: preview.rendererVersion,
        frameCount: composition.frameCount,
        elapsedTimingsCaptured: false,
        pairedHelperAvailable: typeof measurePairedRenderTimings === "function",
      };
    }
    for (let frame = 0; frame < composition.frameCount; frame++) {
      legacy.renderFrame(frame);
      readLegacy();
      preview.renderFrame(frame);
      preview.readPixels();
    }
    for (const frame of [
      composition.frameCount - 1,
      Math.floor(composition.frameCount / 2),
      0,
    ]) {
      preview.renderFrame(frame);
      preview.readPixels();
    }
    const result = measurePairedRenderTimings(
      composition.frameCount,
      { renderFrame: legacy.renderFrame, readPixels: readLegacy },
      { renderFrame: preview.renderFrame, readPixels: preview.readPixels },
    );
    return {
      rendererVersion: preview.rendererVersion,
      frameCount: composition.frameCount,
      ...result,
      withinFamilyTimingBudget: result.ratio <= 1.25,
      strictFamilyAudit: false,
    };
  } finally {
    try {
      preview?.dispose();
    } finally {
      legacy?.dispose();
    }
  }
}

